			t.Errorf("%s (internal/%s): the footer spinner API was removed in DEVDESK-377; use Status.Activity and the shared dot", use, rel)
		}
	})
	if scanned == 0 {
		t.Fatal("no file under internal/ui scanned")
	}
}
